-- generated by ./dev theme from ~/dev/modules/desktop/hyprland/hyprland/templates — edit there, not here
return {
    -- focused window: accent → blue, diagonally
    active_border   = { colors = { "rgb(${accent_raw})", "rgb(${blue_raw})" }, angle = 45 },
    inactive_border = "rgba(${surface_raw}aa)",
    -- soft, low-alpha shadows: depth without a dark halo
    shadow          = 0x66${bg_dim_raw},
    shadow_inactive = 0x33${bg_dim_raw},
    cursor          = "${CURSOR_THEME}",
    active_opacity  = ${WIN_ACTIVE},
    inactive_opacity = ${WIN_INACTIVE},
}
